<?php
namespace Tests\Feature;
use App\Models\AttendanceEntry; use App\Models\Employee; use App\Models\Tenant; use App\Services\BiometricDeviceService; use App\Services\BiometricIngestService; use Illuminate\Support\Str; use Tests\TestCase;
class BiometricIngestTest extends TestCase { public function test_duplicate_biometric_event_is_idempotent():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Bio '.Str::random(4)]);try{tenancy()->initialize($tenant);$e=Employee::create(['name'=>'E','national_id'=>'BIO-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'400.000','status'=>'active']);$ds=app(BiometricDeviceService::class);$r=$ds->create('Clock');$ds->map($r['device'],$e,'42');$payload=['event_id'=>'evt-1','employee_id'=>'42','event_type'=>'in','event_at'=>'2026-09-05T09:00:00+03:00'];$s=app(BiometricIngestService::class);$a=$s->ingest($r['device'],$r['token'],$payload);$b=$s->ingest($r['device'],$r['token'],$payload);$this->assertSame($a->id,$b->id);$this->assertSame(1,AttendanceEntry::count());}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
